const fs = require("fs");
const path = require("path");

const MARK = "V1010513_VULCAN_IMAGE_BLACKOUT_SPOTLIGHT_FIRE_FIX";
const sceneFile = path.join("src", "game", "GameScene.ts");
const assetName = "vulcan-helicopter-topview.png";
const assetDest = path.join("public", "assets", assetName);
const embeddedHelicopterPngBase64 =
  "";

function read(file) {
  if (!fs.existsSync(file)) throw new Error(`Missing ${file}`);
  return fs.readFileSync(file, "utf8").replace(/\r\n/g, "\n");
}
function write(file, text) {
  fs.writeFileSync(file, text, "utf8");
}
function replaceMethod(text, signature, replacement, label) {
  const startNeedle = `    private ${signature}`;
  const start = text.indexOf(startNeedle);
  if (start < 0) throw new Error(`${label}: method start not found: ${signature}. No file written.`);
  const next = text.indexOf("\n    private ", start + startNeedle.length);
  if (next < 0) throw new Error(`${label}: next method not found. No file written.`);
  return text.slice(0, start) + replacement.trimEnd() + "\n" + text.slice(next);
}
function once(text, needle, replacement, label) {
  const count = text.split(needle).length - 1;
  if (count !== 1) throw new Error(`${label}: expected 1 anchor, found ${count}. No file written.`);
  return text.replace(needle, replacement);
}

let scene = read(sceneFile);

if (scene.includes(MARK)) {
  console.log("[skip] v0.10.10.513 already applied.");
  process.exit(0);
}

if (!scene.includes("V1010512_VULCAN_DARK_ENTRY_ORBIT_HOLD_FIRE")) {
  throw new Error("v512c base marker not found. Apply successful v512c first. No file written.");
}

/* Write embedded helicopter sprite into public/assets. */
fs.mkdirSync(path.dirname(assetDest), { recursive: true });

/* Preload the generated helicopter image. */
if (!scene.includes("'vulcan-helicopter-topview'")) {
  scene = once(
    scene,
    `preload(): void {\n`,
    `preload(): void {\n        this.load.image(\n            'vulcan-helicopter-topview',\n            'assets/${assetName}',\n        );\n\n`,
    "Vulcan helicopter image preload",
  );
}

/* Replace the old hand-drawn helicopter entirely with the generated PNG. */
scene = replaceMethod(scene, "createVulcanHelicopter(): void {", `
    private createVulcanHelicopter(): void {
        if (
            this.vulcanHelicopter
        ) {
            this.vulcanHelicopter
                .destroy(true);

            this.vulcanHelicopter =
                undefined;
        }

        this.vulcanHelicopterRotorTween
            ?.stop();

        this.vulcanHelicopterRotorTween =
            undefined;

        const sprite =
            this.add.image(
                0,
                0,
                'vulcan-helicopter-topview',
            )
                .setOrigin(
                    0.5,
                )
                /*
                 * Generated asset points to screen-right.
                 * Rotate nose upward for the entry shot.
                 */
                .setAngle(
                    -90,
                )
                .setDisplaySize(
                    292,
                    195,
                );

        this.vulcanHelicopter =
            this.add.container(
                0,
                0,
                [
                    sprite,
                ],
            )
                .setDepth(
                    25004,
                )
                .setAlpha(
                    0.98,
                )
                .setScale(
                    1,
                )
                .setVisible(
                    false,
                );
    }
`, "replace shape helicopter with generated image");

/*
 * Cinematic:
 * helicopter entry -> 500% punch + real camera fadeOut to guaranteed 100% black
 * -> destroy helicopter -> slower center travel while camera fadeIn
 * -> persistent Vulcan darkness remains -> spotlight POP.
 */
scene = replaceMethod(scene, "enterVulcanCinematic(isOwner: boolean): void {", `
    private enterVulcanCinematic(
        isOwner: boolean,
    ): void {
        if (
            this.phase !==
                'hunt' ||
            !isOwner
        ) {
            return;
        }

        this.vulcanCinematicActive =
            true;

        this.vulcanSpectatorViewActive =
            false;

        this.vulcanSpotlightReveal =
            0;

        this.vulcanFiring =
            false;

        this.vulcanPointerHeld =
            false;

        this.vulcanHeat =
            0;

        this.vulcanReadyAt =
            0;

        /*
         * Vulcan never reveals the normal bright map.
         * Remove Hunter cone/circle immediately and replace it with
         * one persistent restricted-dark aerial layer.
         */
        this.hiderVisionGraphics
            ?.clear()
            .setVisible(false);

        this.hiderVisionOverlays
            .forEach(
                (overlay) =>
                    overlay
                        .setVisible(false),
            );

        this.heartbeatDangerOverlay
            ?.setVisible(false)
            .setAlpha(0);

        this.heartbeatBorders
            .forEach(
                (border) =>
                    border
                        .setVisible(false)
                        .setAlpha(0),
            );

        this.aimLine
            ?.clear()
            .setVisible(false);

        this.crosshair
            ?.clear()
            .setVisible(false);

        this.gun
            ?.setVisible(false);

        this.networkPlayerManager
            ?.clearHunterAimLines();

        this.mobileMoveBase
            ?.setVisible(false);

        this.mobileMoveKnob
            ?.setVisible(false);

        this.mobileMoveLabel
            ?.setVisible(false);

        this.mobileAimBase
            ?.setVisible(false);

        this.mobileAimKnob
            ?.setVisible(false);

        this.mobileAimLabel
            ?.setVisible(false);

        this.mobileFireButton
            ?.setVisible(false);

        this.mobileFireLabel
            ?.setVisible(false);

        this.hunterWeaponHudContainer
            ?.setVisible(false);

        this.vulcanDarkness
            ?.clear()
            .setDepth(
                24993,
            )
            .setVisible(true)
            .setBlendMode(
                Phaser.BlendModes.NORMAL,
            );

        this.vulcanDarkness
            ?.fillStyle(
                0x000103,
                0.60,
            );

        this.vulcanDarkness
            ?.fillRect(
                -260,
                -260,
                1500,
                1060,
            );

        this.vulcanSpotlight
            ?.clear()
            .setVisible(false);

        this.vulcanCooldownGraphics
            ?.clear()
            .setVisible(false);

        this.vulcanCinematicShade
            ?.setVisible(false)
            .setAlpha(0);

        this.createVulcanHelicopter();
        this.startSniperHelicopterAudio();

        const camera =
            this.cameras.main;

        camera
            .resetFX()
            .stopFollow()
            .removeBounds()
            .setSize(
                this.gameWidth,
                this.gameHeight,
            )
            .setRotation(0);

        const startZoom =
            Math.max(
                0.01,
                camera.zoom,
            );

        this.vulcanSavedCameraZoom =
            startZoom;

        const startX =
            camera.midPoint.x;

        const startY =
            camera.midPoint.y;

        const entryY =
            camera.worldView.bottom +
            120 /
                startZoom;

        this.vulcanHelicopter
            ?.setPosition(
                startX,
                entryY,
            )
            .setScale(
                0.82,
            )
            .setAlpha(
                0,
            )
            .setVisible(
                true,
            );

        const beginBlackout =
            (): void => {
                if (
                    this.phase !==
                        'hunt' ||
                    !this.vulcanActive
                ) {
                    return;
                }

                const heliX =
                    this.vulcanHelicopter
                        ?.x ??
                    startX;

                const heliY =
                    this.vulcanHelicopter
                        ?.y ??
                    startY;

                const punchZoom =
                    Phaser.Math.Clamp(
                        startZoom *
                            5,
                        4.8,
                        8,
                    );

                const punch = {
                    value: 0,
                };

                this.playVulcanTransitionWhoosh();

                /*
                 * Camera fadeOut is used here instead of a world rectangle:
                 * it guarantees a true 100% black viewport at max zoom.
                 */
                camera.fadeOut(
                    720,
                    0,
                    0,
                    0,
                );

                this.tweens.add({
                    targets:
                        punch,
                    value:
                        1,
                    duration:
                        720,
                    ease:
                        'Cubic.easeIn',
                    onUpdate:
                        () => {
                            const t =
                                Phaser.Math.Clamp(
                                    punch.value,
                                    0,
                                    1,
                                );

                            const eased =
                                t *
                                t;

                            camera
                                .setZoom(
                                    Phaser.Math.Linear(
                                        startZoom,
                                        punchZoom,
                                        eased,
                                    ),
                                )
                                .centerOn(
                                    heliX,
                                    heliY,
                                );

                            this.applyFixedHudForZoom(
                                camera.zoom,
                            );
                        },
                    onComplete:
                        () => {
                            /*
                             * Hold an actual all-black frame before moving
                             * into the aerial viewpoint.
                             */
                            camera
                                .setZoom(
                                    punchZoom,
                                )
                                .centerOn(
                                    heliX,
                                    heliY,
                                );

                            this.vulcanHelicopter
                                ?.destroy(true);

                            this.vulcanHelicopter =
                                undefined;

                            this.time.delayedCall(
                                260,
                                () => {
                                    if (
                                        this.phase !==
                                            'hunt' ||
                                        !this.vulcanActive
                                    ) {
                                        return;
                                    }

                                    const travel = {
                                        value: 0,
                                    };

                                    /*
                                     * Slower than before: ~3.2 s.
                                     * Start fully black and gradually brighten
                                     * only to the persistent Vulcan darkness.
                                     */
                                    camera.fadeIn(
                                        3200,
                                        0,
                                        0,
                                        0,
                                    );

                                    this.tweens.add({
                                        targets:
                                            travel,
                                        value:
                                            1,
                                        duration:
                                            3200,
                                        ease:
                                            'Sine.easeInOut',
                                        onUpdate:
                                            () => {
                                                const t =
                                                    Phaser.Math.Clamp(
                                                        travel.value,
                                                        0,
                                                        1,
                                                    );

                                                const eased =
                                                    Phaser.Math.SmoothStep(
                                                        t,
                                                        0,
                                                        1,
                                                    );

                                                camera
                                                    .setZoom(
                                                        Phaser.Math.Linear(
                                                            punchZoom,
                                                            1.34,
                                                            eased,
                                                        ),
                                                    )
                                                    .centerOn(
                                                        Phaser.Math.Linear(
                                                            heliX,
                                                            480,
                                                            eased,
                                                        ),
                                                        Phaser.Math.Linear(
                                                            heliY,
                                                            270,
                                                            eased,
                                                        ),
                                                    )
                                                    .setRotation(
                                                        0,
                                                    );

                                                this.applyFixedHudForZoom(
                                                    camera.zoom,
                                                );
                                            },
                                        onComplete:
                                            () => {
                                                if (
                                                    this.phase !==
                                                        'hunt' ||
                                                    !this.vulcanActive
                                                ) {
                                                    return;
                                                }

                                                camera
                                                    .resetFX()
                                                    .setZoom(
                                                        1.34,
                                                    )
                                                    .centerOn(
                                                        480,
                                                        270,
                                                    )
                                                    .setRotation(
                                                        0,
                                                    );

                                                this.vulcanTargetX =
                                                    480;

                                                this.vulcanTargetY =
                                                    270;

                                                this.vulcanDisplayX =
                                                    480;

                                                this.vulcanDisplayY =
                                                    270;

                                                this.vulcanOrbitStartedAt =
                                                    this.time.now;

                                                /*
                                                 * Make the lamp explicitly visible
                                                 * BEFORE enabling input.
                                                 */
                                                this.vulcanSpotlightReveal =
                                                    1;

                                                this.vulcanSpotlight
                                                    ?.setDepth(
                                                        25003,
                                                    )
                                                    .setVisible(
                                                        true,
                                                    );

                                                this.vulcanCooldownGraphics
                                                    ?.setDepth(
                                                        25005,
                                                    )
                                                    .setVisible(
                                                        true,
                                                    );

                                                this.drawVulcanSpotlight(
                                                    480,
                                                    270,
                                                );

                                                this.drawVulcanCooldownGauge(
                                                    480,
                                                    270,
                                                );

                                                this.playVulcanSearchlightPop();

                                                const pop =
                                                    this.add.circle(
                                                        480,
                                                        270,
                                                        38,
                                                        0xffffdd,
                                                        0.96,
                                                    )
                                                        .setDepth(
                                                            25006,
                                                        );

                                                this.tweens.add({
                                                    targets:
                                                        pop,
                                                    scale:
                                                        5.8,
                                                    alpha:
                                                        0,
                                                    duration:
                                                        320,
                                                    ease:
                                                        'Quad.easeOut',
                                                    onComplete:
                                                        () =>
                                                            pop.destroy(),
                                                });

                                                /*
                                                 * Input becomes live only after
                                                 * the lamp is already on screen.
                                                 */
                                                this.vulcanCinematicActive =
                                                    false;

                                                if (
                                                    this.practiceMode !==
                                                    'hunter'
                                                ) {
                                                    multiplayerClient
                                                        .sendVulcanAim(
                                                            480,
                                                            270,
                                                        );
                                                }
                                            },
                                    });
                                },
                            );
                        },
                });
            };

        if (
            this.vulcanHelicopter
        ) {
            this.tweens.add({
                targets:
                    this.vulcanHelicopter,
                y:
                    startY,
                alpha:
                    1,
                scaleX:
                    1.02,
                scaleY:
                    1.02,
                duration:
                    760,
                ease:
                    'Cubic.easeOut',
                onComplete:
                    beginBlackout,
            });
        } else {
            beginBlackout();
        }
    }
`, "guaranteed blackout and slow aerial transfer");

/* Make the actual spotlight impossible to hide behind its darkness layer. */
scene = replaceMethod(scene, "drawVulcanSpotlight(x: number, y: number): void {", `
    private drawVulcanSpotlight(
        x: number,
        y: number,
    ): void {
        const light =
            this.vulcanSpotlight;

        const darkness =
            this.vulcanDarkness;

        if (
            !light ||
            !darkness
        ) {
            return;
        }

        const dx =
            x -
            480;

        const dy =
            y -
            270;

        const distance =
            Math.hypot(
                dx,
                dy,
            );

        const t =
            Phaser.Math.Clamp(
                distance /
                    Math.hypot(
                        480,
                        270,
                    ),
                0,
                1,
            );

        const angle =
            Math.atan2(
                dy,
                dx,
            );

        /*
         * Larger than v512:
         * center = 144x144 circle,
         * far edge = 350x86 directional ellipse.
         */
        const major =
            Phaser.Math.Linear(
                144,
                350,
                t,
            );

        const minor =
            Phaser.Math.Linear(
                144,
                86,
                t,
            );

        const intensity =
            Phaser.Math.Linear(
                1,
                0.76,
                t,
            );

        darkness
            .clear()
            .setDepth(
                24993,
            )
            .setVisible(
                true,
            )
            .setBlendMode(
                Phaser.BlendModes.NORMAL,
            );

        darkness.fillStyle(
            0x000103,
            0.60,
        );

        darkness.fillRect(
            -260,
            -260,
            1500,
            1060,
        );

        light
            .clear()
            .setDepth(
                25003,
            )
            .setPosition(
                x,
                y,
            )
            .setRotation(
                angle,
            )
            .setBlendMode(
                Phaser.BlendModes.ADD,
            )
            .setVisible(
                true,
            );

        light.fillStyle(
            0xffc94f,
            0.24 *
                intensity,
        );

        light.fillEllipse(
            0,
            0,
            major *
                3.2,
            minor *
                3.2,
        );

        light.fillStyle(
            0xffdf72,
            0.36 *
                intensity,
        );

        light.fillEllipse(
            0,
            0,
            major *
                2.35,
            minor *
                2.35,
        );

        light.fillStyle(
            0xffffb0,
            0.58 *
                intensity,
        );

        light.fillEllipse(
            0,
            0,
            major *
                1.65,
            minor *
                1.65,
        );

        light.fillStyle(
            0xffffff,
            0.94 *
                intensity,
        );

        light.fillEllipse(
            0,
            0,
            major,
            minor,
        );

        light.lineStyle(
            4,
            0xffee9b,
            0.94,
        );

        light.strokeEllipse(
            0,
            0,
            major,
            minor,
        );
    }
`, "always-visible large spotlight");

/*
 * Reinforce aerial update.
 * Existing server/spectator behavior is retained, but local owner no longer
 * depends on spotlight.visible/reveal to enter the update loop.
 */
const updateSig = "updateVulcanAirSupport(): void {";
const updateStart = scene.indexOf(`    private ${updateSig}`);
if (updateStart < 0) throw new Error("updateVulcanAirSupport not found. No file written.");
const updateEnd = scene.indexOf("\n    private ", updateStart + 20);
if (updateEnd < 0) throw new Error("updateVulcanAirSupport end not found. No file written.");
let updateBlock = scene.slice(updateStart, updateEnd);

/* Delete the deadlock gates that returned before spotlight draw/input state could recover. */
updateBlock = updateBlock.replace(
/        if \(\n            this\.vulcanCinematicActive &&[\s\S]*?        \}\n\n        if \(\n            this\.vulcanSpotlightReveal <=[\s\S]*?        \}\n\n/,
`        if (
            this.vulcanCinematicActive
        ) {
            return;
        }

        /*
         * Once the cinematic is over, local Vulcan support owns a visible lamp
         * unconditionally. This prevents the old visibility/input deadlock.
         */
        if (
            this.vulcanActive
        ) {
            this.vulcanSpotlightReveal =
                1;

            this.vulcanSpotlight
                ?.setDepth(
                    25003,
                )
                .setVisible(
                    true,
                );

            this.vulcanCooldownGraphics
                ?.setDepth(
                    25005,
                )
                .setVisible(
                    true,
                );
        }

`,
);

if (!updateBlock.includes("this.vulcanSpotlightReveal =")) {
  throw new Error("Could not repair Vulcan update visibility gate. No file written.");
}

/* Slightly slower, more readable orbit, but with visible displacement. */
updateBlock = updateBlock
  .replace(/0\.00060/g, "0.00048")
  .replace(
    /Math\.cos\(\s*orbit,\s*\)\s*\*\s*22/g,
    "Math.cos(orbit) * 24",
  )
  .replace(
    /Math\.sin\(\s*orbit,\s*\)\s*\*\s*14/g,
    "Math.sin(orbit) * 16",
  );

scene = scene.slice(0, updateStart) + updateBlock + scene.slice(updateEnd);

/*
 * Replace Vulcan POINTER_DOWN/UP handlers.
 * Do NOT gate firing on spotlight.visible; cinematic completion is the only gate.
 * Cooling begins instantly client-side and server later confirms it.
 */
const pointerRegex =
/        this\.input\.on\(Phaser\.Input\.Events\.POINTER_DOWN, \(pointer: Phaser\.Input\.Pointer\) => \{[\s\S]*?        this\.input\.on\(Phaser\.Input\.Events\.POINTER_UP_OUTSIDE, stopVulcanPointerFire\);\n/;

const pointerMatch = scene.match(pointerRegex);
if (!pointerMatch) {
  throw new Error("Vulcan pointer handlers not found. No file written.");
}

const pointerReplacement = `        this.input.on(
            Phaser.Input.Events.POINTER_DOWN,
            (
                pointer:
                    Phaser.Input.Pointer,
            ) => {
                if (
                    !this.vulcanActive ||
                    this.phase !==
                        'hunt' ||
                    this.vulcanCinematicActive
                ) {
                    return;
                }

                const now =
                    Date.now();

                if (
                    this.vulcanFiring ||
                    now <
                        this.vulcanReadyAt ||
                    this.vulcanHeat >
                        0.001
                ) {
                    return;
                }

                pointer.event
                    ?.preventDefault?.();

                const world =
                    pointer.positionToCamera(
                        this.cameras.main,
                    ) as Phaser.Math.Vector2;

                this.vulcanTargetX =
                    Phaser.Math.Clamp(
                        world.x,
                        0,
                        960,
                    );

                this.vulcanTargetY =
                    Phaser.Math.Clamp(
                        world.y,
                        0,
                        540,
                    );

                this.vulcanPointerHeld =
                    true;

                this.vulcanFiring =
                    true;

                this.vulcanFireStartedAt =
                    now;

                this.vulcanLastMuzzleFxAt =
                    0;

                /*
                 * Immediate local feedback: sound + first HEAT frame.
                 */
                this.vulcanHeat =
                    0.001;

                this.playVulcanGunPulse();

                if (
                    this.practiceMode !==
                    'hunter'
                ) {
                    multiplayerClient
                        .sendVulcanAim(
                            this.vulcanTargetX,
                            this.vulcanTargetY,
                        );

                    multiplayerClient
                        .sendVulcanFireStart();
                }
            },
        );

        const stopVulcanPointerFire =
            (): void => {
                if (
                    !this.vulcanPointerHeld &&
                    !this.vulcanFiring
                ) {
                    return;
                }

                const now =
                    Date.now();

                const heldMs =
                    Math.max(
                        80,
                        Math.min(
                            3000,
                            now -
                                this.vulcanFireStartedAt,
                        ),
                    );

                this.vulcanPointerHeld =
                    false;

                this.vulcanFiring =
                    false;

                this.vulcanHeat =
                    Phaser.Math.Clamp(
                        heldMs /
                            3000,
                        0,
                        1,
                    );

                this.vulcanCoolingStartedAt =
                    now;

                this.vulcanCoolingDurationMs =
                    heldMs *
                    2;

                this.vulcanReadyAt =
                    now +
                    this.vulcanCoolingDurationMs;

                if (
                    this.practiceMode !==
                    'hunter'
                ) {
                    multiplayerClient
                        .sendVulcanFireStop();
                }
            };

        this.input.on(
            Phaser.Input.Events.POINTER_UP,
            stopVulcanPointerFire,
        );

        this.input.on(
            Phaser.Input.Events.POINTER_UP_OUTSIDE,
            stopVulcanPointerFire,
        );
`;

scene = scene.replace(pointerRegex, pointerReplacement);

/* Make sure pointer movement broadcasts/follows while held. */
scene = scene.replace(
  /if \(\s*!this\.vulcanActive \|\|[\s\S]{0,180}?this\.phase !==\s*'hunt'[\s\S]{0,80}?\) \{\s*return;\s*\}/,
  (block) => block,
);

/* Marker. */
scene =
  `/* ${MARK}: generated helicopter sprite; guaranteed camera full-black; slower fade-in center travel; spotlight visibility deadlock removed; hold-fire and HEAT gauge restored. */\n` +
  scene;

/* Minimal robust checks, not brittle numeric formatting checks. */
const checks = [
  ["asset preload", /vulcan-helicopter-topview/],
  ["image helicopter", /this\.add\.image\(/],
  ["camera true blackout", /camera\.fadeOut\(/],
  ["slow fade in", /camera\.fadeIn\(/],
  ["helicopter destroy", /this\.vulcanHelicopter[\s\S]{0,120}\.destroy\(true\)/],
  ["spotlight always visible", /this\.vulcanSpotlight[\s\S]{0,100}\.setVisible\(\s*true/],
  ["pointer hold start", /this\.vulcanPointerHeld\s*=\s*true/],
  ["proportional cooling", /this\.vulcanCoolingDurationMs\s*=\s*heldMs\s*\*\s*2/],
  ["gun sound", /this\.playVulcanGunPulse\(\)/],
];

for (const [label, re] of checks) {
  if (!re.test(scene)) {
    throw new Error(`Postcondition missing: ${label}. No file written.`);
  }
}

/* Write source only after all checks pass. */
fs.mkdirSync(".patch-backups", { recursive: true });
write(
  path.join(".patch-backups", "GameScene-before-v513.ts"),
  read(sceneFile),
);

fs.writeFileSync(
  assetDest,
  Buffer.from(
    embeddedHelicopterPngBase64,
    "base64",
  ),
);
